/* CSS Kutu Modeli Örneği */
.card {
    width: 300px;
    padding: 20px; /* İç boşluk */
    border: 2px solid #3b82f6; /* Kenarlık */
    margin: 15px auto; /* Dış boşluk & Ortala */
    background-color: #ffffff;
    border-radius: 8px;
    box-sizing: border-box; /* Genişlik hesabına padding dahil et */
}

/* Flexbox ile Ortalanmış Menü */
.navbar {
    display: flex;
    justify-content: space-between; /* İki uca yasla */
    align-items: center; /* Dikeyde ortala */
}

/* CSS Grid ile 3 Sütunlu Kart Düzeni */
.grid-container {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 20px; /* Kartlar arası boşluk */
}

/* Mobil Öncelikli Tasarım */
.container {
    width: 100%;
    padding: 15px;
}

/* Masaüstü Ekranlar (768px ve üzeri) */
@media (min-width: 768px) {
    .container {
        width: 750px;
        margin: 0 auto;
    }
}
